import requests
queries=['emergency medicine systematic reviews trial registries','emergency department systematic review ClinicalTrials.gov registry search','emergency medicine journals systematic review registry searching']
for q in queries:
 r=requests.get('https://www.ebi.ac.uk/europepmc/webservices/rest/search',params={'query':q,'format':'json','pageSize':25,'resultType':'core'},timeout=25)
 print('\nQUERY:',q,'STATUS',r.status_code)
 for x in r.json().get('resultList',{}).get('result',[]):
  t=x.get('title','')
  if any(w in t.lower() for w in ['registry','registries','emergency medicine','clinical trial']):
   print(x.get('title'),'|',x.get('journalTitle'),'|',x.get('pubYear'),'| PMID',x.get('pmid'),'| DOI',x.get('doi'))
   print((x.get('abstractText') or '')[:2200])

import requests
for q in ['Do systematic reviews published in emergency medicine journals routinely search clinical trials registries','systematic reviews emergency medicine journals registry searches cross-sectional analysis']:
 r=requests.get('https://api.crossref.org/works',params={'query.title':q,'rows':8},timeout=25)
 print('\nQUERY',q,'status',r.status_code)
 for x in r.json().get('message',{}).get('items',[]):
  print('TITLE:',x.get('title',[''])[0],'YEAR:',(x.get('published-print') or x.get('published-online') or {}).get('date-parts'),'JOURNAL:',x.get('container-title',['']),'DOI:',x.get('DOI'))

